func capnpBuildNested(v *ds.Nested) (*capnp.Message, error) {
	msg, seg, err := capnp.NewMessage(capnp.SingleSegment(nil))
	if err != nil {
		return nil, err
	}
	root, err := cp.NewRootNested(seg)
	if err != nil {
		return nil, err
	}
	return msg, buildCPNested(root, v)
}

func capnpReadNested(msg *capnp.Message, v *ds.Nested) error {
	root, err := cp.ReadRootNested(msg)
	if err != nil {
		return err
	}
	return readCPNested(root, v)
}

